const values = $input.first().json.values || [];
if (values.length < 1) throw new Error('Prospects sheet read returned no rows');

const header = values[0].map(v => String(v).trim());
const idx = {};
for (const col of ['prospect_id', 'status', 'opener_sent_at', 'last_touch']) {
  idx[col] = header.indexOf(col);
  if (idx[col] === -1) throw new Error('Column missing from Prospects header: ' + col);
}

const rows = values.slice(1).filter(r => String(r[idx.prospect_id] || '').trim().startsWith('OP-'));
const get = (r, c) => String(r[idx[c]] || '').trim();

const counts = {};
let queue = 0;
for (const r of rows) {
  const s = get(r, 'status') || '(blank)';
  counts[s] = (counts[s] || 0) + 1;
  if (s === 'queued' || s === '(blank)') queue++;
}

const sendDates = rows.map(r => get(r, 'opener_sent_at')).filter(Boolean).sort();
const lastSend = sendDates.length ? sendDates[sendDates.length - 1] : 'none recorded';
const touchDates = rows.map(r => get(r, 'last_touch')).filter(Boolean).sort();
const lastTouch = touchDates.length ? touchDates[touchDates.length - 1] : 'none recorded';

const today = new Date().toLocaleDateString('en-AU', { timeZone: 'Australia/Sydney', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
const statusLines = Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([k, v]) => '\u2022 ' + k + ': ' + v).join('\n');

let message = '\uD83E\uDEC0 DA outbound heartbeat (' + today + ')\n'
  + 'Queue going into today: ' + queue + '\n'
  + 'Prospects tracked: ' + rows.length + '\n'
  + statusLines + '\n'
  + 'Last opener sent: ' + lastSend + '\n'
  + 'Last touch: ' + lastTouch;
if (queue === 0) message += '\n\u26A0\uFE0F Queue is EMPTY: workflow-f has nothing to draft. Source or load prospects.';

return [{ json: { message, queue, total: rows.length } }];
